ALTER TABLE combo_offers ADD COLUMN discount_percent DECIMAL(6,2) NOT NULL DEFAULT 0 AFTER regular_price;
CREATE TABLE IF NOT EXISTS combo_offer_custom_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,combo_offer_id INT UNSIGNED NOT NULL,item_name VARCHAR(180) NOT NULL,item_price DECIMAL(12,2) NOT NULL DEFAULT 0,thumbnail_path VARCHAR(500) NULL,sort_order INT NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_combo_custom_items (combo_offer_id,sort_order),CONSTRAINT fk_combo_custom_offer FOREIGN KEY (combo_offer_id) REFERENCES combo_offers(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
